package dev.swagkeys;

import android.content.Context;
import android.graphics.Paint;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The complete emoji set, loaded from {@code assets/emoji.txt} (generated by
 * {@code tools/build_emoji.py} from Unicode emoji-test.txt): every fully-qualified emoji, grouped
 * by CLDR category, with skin-tone variants attached to their base emoji. Entries the device's
 * fonts cannot draw as a single glyph (newer than the installed emoji font) are dropped.
 */
public final class EmojiData {

    public static final class Category {
        /** Emoji shown on the category tab. */
        public final String icon;
        /** String resource naming the category for accessibility. */
        public final int nameRes;
        /** Base emoji (no skin tone) in Unicode order. */
        public final List<String> emojis;

        Category(String icon, int nameRes, List<String> emojis) {
            this.icon = icon;
            this.nameRes = nameRes;
            this.emojis = emojis;
        }
    }

    private static final String ASSET = "emoji.txt";

    /** Loaded data, published once; readers never block on a loader once it is set. */
    private static final class Data {
        final List<Category> categories;
        /** Base emoji -> base followed by its renderable skin-tone variants (only if any). */
        final Map<String, List<String>> variants;

        Data(List<Category> categories, Map<String, List<String>> variants) {
            this.categories = categories;
            this.variants = variants;
        }
    }

    private static volatile Data data;

    private EmojiData() {}

    /** Loads the data on a background thread so the first panel open does not stall. */
    public static void preload(Context context) {
        Context app = context.getApplicationContext();
        // Normal priority: a low-priority thread would be throttled into the background cgroup
        // while the UI thread might be waiting for the same data.
        Thread t = new Thread(() -> categories(app), "emoji-preload");
        t.setDaemon(true);
        t.start();
    }

    public static List<Category> categories(Context context) {
        return get(context).categories;
    }

    /**
     * The base emoji followed by its renderable skin-tone variants, or an empty list if it has
     * none.
     */
    public static List<String> variantsOf(Context context, String base) {
        List<String> v = get(context).variants.get(base);
        return v == null ? Collections.emptyList() : v;
    }

    private static Data get(Context context) {
        Data d = data;
        if (d != null) return d;
        // Computed without holding a lock; if two threads race, both results are identical and
        // the first one published wins.
        Data loaded = load(context);
        synchronized (EmojiData.class) {
            if (data == null) data = loaded;
            return data;
        }
    }

    private static Data load(Context context) {
        List<String[]> groups = new ArrayList<>();          // {id, icon}
        List<List<String>> bases = new ArrayList<>();
        Map<String, List<String>> tones = new HashMap<>();
        try (InputStream in = context.getAssets().open(ASSET);
             BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            String line;
            while ((line = r.readLine()) != null) {
                if (line.isEmpty() || line.startsWith("//")) continue;
                if (line.startsWith("@")) {
                    groups.add(line.substring(1).split(" ", 2));
                    bases.add(new ArrayList<>());
                    continue;
                }
                if (bases.isEmpty()) continue;
                String[] parts = line.split(" ");
                bases.get(bases.size() - 1).add(parts[0]);
                if (parts.length > 1) {
                    List<String> all = new ArrayList<>(parts.length);
                    Collections.addAll(all, parts);
                    tones.put(parts[0], all);
                }
            }
        } catch (IOException e) {
            throw new IllegalStateException("missing asset " + ASSET, e);
        }

        Paint paint = new Paint();
        boolean fontReportsGlyphs = false;
        List<Category> cats = new ArrayList<>(groups.size());
        for (int i = 0; i < groups.size(); i++) {
            List<String> renderable = filter(bases.get(i), paint);
            fontReportsGlyphs |= !renderable.isEmpty();
            cats.add(new Category(groups.get(i)[1], nameRes(groups.get(i)[0]),
                    Collections.unmodifiableList(renderable)));
        }
        if (!fontReportsGlyphs) {
            // A font stack that reports no emoji glyphs at all (a stripped test runtime) would
            // leave the panel empty; show the unfiltered data instead.
            cats.clear();
            for (int i = 0; i < groups.size(); i++) {
                cats.add(new Category(groups.get(i)[1], nameRes(groups.get(i)[0]),
                        Collections.unmodifiableList(bases.get(i))));
            }
        }
        Map<String, List<String>> v = new HashMap<>();
        for (Map.Entry<String, List<String>> e : tones.entrySet()) {
            List<String> renderable = fontReportsGlyphs ? filter(e.getValue(), paint) : e.getValue();
            if (renderable.size() > 1) v.put(e.getKey(), Collections.unmodifiableList(renderable));
        }
        return new Data(Collections.unmodifiableList(cats), v);
    }

    private static List<String> filter(List<String> emojis, Paint paint) {
        List<String> out = new ArrayList<>(emojis.size());
        for (String e : emojis) {
            if (paint.hasGlyph(e)) out.add(e);
        }
        return out;
    }

    private static int nameRes(String groupId) {
        switch (groupId) {
            case "smileys": return R.string.a11y_emoji_smileys;
            case "people": return R.string.a11y_emoji_people;
            case "nature": return R.string.a11y_emoji_nature;
            case "food": return R.string.a11y_emoji_food;
            case "travel": return R.string.a11y_emoji_travel;
            case "activities": return R.string.a11y_emoji_activity;
            case "objects": return R.string.a11y_emoji_objects;
            case "symbols": return R.string.a11y_emoji_symbols;
            case "flags": return R.string.a11y_emoji_flags;
            default: return R.string.a11y_emoji;
        }
    }
}
